p=Path('dementor-lab/tests/browser-smoke.mjs')
s=p.read_text()
s=s.replace("await page.locator('[data-brain-preset=\"always-right\"]').click();await addNode('repeat');assert.equal(await page.locator('#to-setup').isDisabled(),false,'authored preset plus a second repeat stays runnable');", "await page.locator('[data-brain-preset=\"always-right\"]').click();assert.equal(await page.locator('#to-setup').isDisabled(),false,'terminal REPEAT preset stays runnable without a dead continuation');")
s=s.replace("assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),5,'preset body stays compact after trigger infrastructure is projected into the hub');", "assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),4,'preset body stays compact after trigger infrastructure is projected into the hub');")
s=s.replace("const replayRepeats=page.locator('#brain-graph .brain-stack-node').filter({has:page.locator('.brain-stack-title',{hasText:/^REPEAT$/})});assert.equal(await replayRepeats.count(),2,'replay fixture contains two same-type nodes');assert.equal(await page.locator('#brain-graph .brain-stack-node.locked').filter({has:page.locator('.brain-stack-title',{hasText:/^REPEAT$/})}).count(),1,'only the exact suspicious repeat node is unlocked');", "const replayRepeats=page.locator('#brain-graph .brain-stack-node').filter({has:page.locator('.brain-stack-title',{hasText:/^REPEAT$/})});assert.equal(await replayRepeats.count(),1,'replay keeps the authored terminal repeat node');assert.equal(await page.locator('#brain-graph .brain-stack-node.locked').filter({has:page.locator('.brain-stack-title',{hasText:/^REPEAT$/})}).count(),0,'the exact suspicious repeat node remains editable in replay');")
